#include <cstdio>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    long long c;
    while (true) {
        scanf("%d", &n);
        if (n == 0) break;

        vector<int> t(n);
        c = 0;

        for (int i = 0; i < n; i++) {
            scanf("%d", &t[i]);
        }

        sort(t.begin(), t.end());

        // Instead of iterating to accumulate the sum, we can use a prefix sum approach.
        long long prefixSum = 0;

        for (int i = 0; i < n; i++) {
            c += prefixSum; // Add the current prefix sum to the total count
            prefixSum += t[i]; // Update the prefix sum
        }

        printf("%lld\n", c);
    }
    return 0;
}

